def finding(item,n,refs):
    fid,name,primary,required=item; low=name.lower(); kinds=[primary,KINDS[(n+5)%len(KINDS)],KINDS[(n+13)%len(KINDS)]]
    return {"id":fid,"name":name,"description":f"Records {low} as source-qualified report context while incident, system, investigation, authority, remediation, evidence and records masters remain external.","source_refs":refs,"questions":[
      {"id":f"{fid}-q01","text":f"What stable identity, report version, jurisdiction-qualified value and explicit unknown establish {low}?","kind":kinds[0],"answer_data":["report, incident and external master identifiers","typed value, source and applicable regime","unknown, withheld, disputed and not-applicable states"]},
      {"id":f"{fid}-q02","text":f"Who observed, asserted, reviewed, approved, received or may rely on {low}, under which authority and limits?","kind":kinds[1],"answer_data":["actor, role, organization and contact","authority, mandate, purpose, policy and access","conflict, contest, exception and escalation"]},
      {"id":f"{fid}-q03","text":f"Which occurrence, awareness, effective, submitted, recorded, ingested and knowledge times, evidence and uncertainty qualify {low}?","kind":kinds[2],"answer_data":["distinct event and knowledge times","evidence, method, confidence and uncertainty","successor, correction, retention and audit"]}],
      "data_elements":[{"id":f"{fid}-data","name":f"{name} data","description":f"Typed incident-report data for {low}, qualified by report version, jurisdiction, source, authority, time, evidence and provenance.","value_kind":"collection","cardinality":"1" if required else "0..n","required":required,"source_refs":refs}],
      "artifacts":[{"id":f"{fid}-record","name":f"{name} record","description":f"Immutable or successor-versioned report evidence for {low}.","media_or_form":["logical AI incident report assertion","fact, assessment, impact, response, submission, correction or evidence record"],"serial":True,"identity_strategy":f"Report-case ID plus independent assertion, submission, decision, event or artifact ID for {fid}; incident title, date, URL and digest never identify the report alone.","source_refs":refs}],"inline_only_rationale":None}

def structure():
    bundles=[]; n=0
    for bid,bname,rationale,layers in ROWS:
      rendered=[]
      for lid,lname,refs,items in layers:
        fs=[]
        for item in items: n+=1; fs.append(finding(item,n,refs))
        rendered.append({"id":lid,"name":lname,"description":f"Groups source-qualified report context for {lname.lower()}.","source_refs":refs,"findings":fs})
      bundles.append({"id":bid,"name":bname,"description":f"Groups governed report context for {bname.lower()}.","rationale":rationale+".","source_refs":sorted({r for layer in layers for r in layer[2]}),"layers":rendered})
    return {"bundles":bundles}

